local hopping = false
local function joinLowest()
    if hopping then return end
    hopping = true
    local placeId = game.PlaceId
    local best, bestJob, cursor = nil, nil, ""
    for _ = 1, 12 do
        local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(placeId)
        if cursor ~= "" then url = url .. "&cursor=" .. cursor end
        local body = httpGet(url)
        if not body then break end
        local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
        if not ok or type(data) ~= "table" then break end
        for _, s in ipairs(data.data or {}) do
            if type(s.playing) == "number" and s.id ~= game.JobId and s.playing < (s.maxPlayers or 999) then
                if not best or s.playing < best then best, bestJob = s.playing, s.id end
            end
        end
        if data.nextPageCursor and data.nextPageCursor ~= "" then cursor = data.nextPageCursor else break end
        task.wait(0.15)
    end
    if bestJob then
        log("Uniéndose al servidor más vacío (" .. tostring(best) .. " jugadores)")
        pcall(function() TeleportService:TeleportToPlaceInstance(placeId, bestJob, lp) end)
    else
        log("No se encontró servidor vacío, reintenta")
    end
    hopping = false
end

