        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format("Espera %d segundos antes de enviar de nuevo.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText("El mensaje está vacío.") end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText("El mensaje es demasiado largo (máximo 500 caracteres).") end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText("No se permiten enlaces.") end); return
        end
        pcall(function() fbStatus:SetText("Enviando...") end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText("Enviado. ¡Gracias!") end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                log("Tu comentario fue enviado. ¡Gracias!")
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("Error al enviar: " .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel("Máximo 3 mensajes por hora. Sin enlaces ni menciones.", true)

freeBuy = Toggles.s_freebuy and Toggles.s_freebuy.Value ~= false
installActionHook()

